<script setup>
import { computed } from 'vue'
import { Sprout, MapPin, Languages, UserRound, Mail, Pencil, Leaf, ShieldCheck, Fence } from 'lucide-vue-next'
const props = defineProps({ user: { type: Object, required: true } })
const emit = defineEmits(['edit'])
const farmType = computed(() => ({ crops: 'Crop farm', livestock: 'Livestock farm', poultry: 'Poultry farm', mixed: 'Mixed farm' })[props.user.farmType] || 'Farm type not set')
const enterprises = computed(() => (Array.isArray(props.user.mainEnterprises) ? props.user.mainEnterprises : String(props.user.mainEnterprises || '').split(',')).map(value => String(value).trim()).filter(Boolean))
</script>
<template>
  <section class="farm-profile" aria-labelledby="farm-profile-title">
    <header class="profile-cover"><span class="profile-emblem"><Sprout :size="50" :stroke-width="1.6" aria-hidden="true" /></span><div><p>{{ farmType }}</p><h1 id="farm-profile-title">{{ user.farmName || 'My farm' }}</h1><span class="profile-location"><MapPin :size="16" aria-hidden="true" />{{ user.location || 'Add your town in Settings' }}</span></div><button type="button" @click="emit('edit')"><Pencil :size="17" aria-hidden="true" />Edit farm</button></header>
    <div class="profile-body"><section class="profile-growing"><div class="profile-heading"><Leaf :size="23" aria-hidden="true" /><h2>What’s growing here</h2></div><ul v-if="enterprises.length"><li v-for="(enterprise,index) in enterprises" :key="index"><span class="enterprise-mark"><Sprout v-if="user.farmType === 'crops'" :size="26" aria-hidden="true" /><Fence v-else :size="26" aria-hidden="true" /></span>{{ enterprise }}</li></ul><div v-else class="profile-invitation"><Sprout :size="42" aria-hidden="true" /><p>Add your crops and animals so your farm is easier to recognise.</p><button type="button" @click="emit('edit')">Add farm details</button></div></section><section class="profile-contact"><div class="profile-heading"><UserRound :size="23" aria-hidden="true" /><h2>The farmer behind it</h2></div><dl><div><dt><UserRound :size="17" aria-hidden="true" />Farmer</dt><dd>{{ user.name || 'Not provided' }}</dd></div><div><dt><Mail :size="17" aria-hidden="true" />Private email</dt><dd>{{ user.email || 'Not provided' }}</dd></div><div><dt><Languages :size="17" aria-hidden="true" />Preferred language</dt><dd>{{ user.preferredLanguage || 'Not set' }}</dd></div></dl></section></div>
    <aside class="profile-privacy"><ShieldCheck :size="23" aria-hidden="true" /><div><strong>Your private farm profile</strong><p>This page is not a public listing. Choose what to share in Marketplace and Nearby farmers. Farm passport verification is not available.</p></div></aside>
  </section>
</template>
